values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'vidya-niketan' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"When do admissions start?","answer":"Admissions open in November for the next session starting in April."},{"question":"Is transport available?","answer":"Yes. GPS-enabled buses cover 38 routes across the city with a female attendant on each bus."},{"question":"What documents are needed?","answer":"Birth certificate, Aadhaar card, photographs, previous report card and transfer certificate where applicable."},{"question":"Do you offer fee concessions?","answer":"Sibling and merit concessions are available. Ask the office for details."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
