values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'pragati-classes' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"Your dream college starts","highlight":"right here","text":"Small batches, experienced IIT and AIIMS faculty, weekly tests and personal mentoring for every student.","primaryButton":{"label":"Register for test","href":"/contact"},"secondaryButton":{"label":"View courses","href":"/courses"},"badges":[{"label":"3,800+ selections"},{"label":"40 expert faculty"},{"label":"25 students per batch"},{"label":"18 yrs of results"}],"image":{"src":"/themes/pragati-classes/hero.svg","alt":"Pragati Classes"},"smallImage":{"src":"/themes/pragati-classes/scene-2.svg","alt":"NEET-UG"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required"