insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'pragati-classes' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"When do new batches start?","answer":"New batches start in April and June, with a droppers batch in May."},{"question":"Is there a scholarship?","answer":"Yes. Our scholarship test offers up to 90% fee waiver."},{"question":"Are online classes available?","answer":"Yes. All courses run in live online mode with recordings."},{"question":"Is hostel facility available?","answer":"We help outstation students find safe, verified hostels nearby."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'pragati-classes';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'pragati-classes' and c.slug in ('coaching-institute', 'online-education');

