select id, '1.0.0', 'lakshya-academy', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"campus-hero","props":{"eyebrow":"UPSC · State PSC · SSC · Banking","title":"Turn your dream of public service into reality","text":"Structured classroom and online programmes, answer-writing practice and personal mentorship from experienced faculty and former officers.","primaryButton":{"label":"Book free counselling","href":"/contact"},"secondaryButton":{"label":"View courses","href":"/courses"},"image":{"src":"/themes/lakshya-academy/hero.svg","alt":"Lakshya IAS Academy"},"facts":[{"value":"420+","label":"Selections"},{"value":"15 yrs","label":"Experience"},{"value":"1:1","label":"Mentorship"},{"value":"Hindi & English","label":"Medium"}]}},{"type":"quick-links","props":{"items":[{"title":"Courses","text":"UPSC Foundation","icon":"landmark","href":"/courses"},{"title":"About us","text":"Experienced faculty","icon":"book","href":"/about"},{"title":"Results","text":"See our work","icon":"target","href":"/results"},{"title":"Contact","text":"Every day · 8:00 AM – 9:00 PM","icon":"newspaper","href":"/contact"}]}},{"type":"welcome","props":{"eyebrow":"Director''s message","title":"Preparation with purpose","text":"Civil services preparation is a long journey. We keep it focused with a clear syllabus plan, daily current affairs, regular tests and mentors who have walked the same path.","quote":"Consistency beats intensity. Show up every day.","name":"Shri R. K. Srivastava","role":"Director","image":{"src":"/themes/lakshya-academy/place-1.svg","alt":"Shri R. K. Srivastava"},"button":{"label":"About us","href":"/about"}}},{"type":"stats","props":{"items":[{"value":"420+","label":"Selections"},{"value":"15 yrs","label":"Experience"},{"value":"1:1","label":"Mentorship"},{"value":"Hindi & English","label":"Medium"}]}},{"type":"programs","props":{"eyebrow":"Courses","title":"Programmes for every exam","text":"Available in Hindi and English medi