values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'skillsetu' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Do you guarantee placement?","answer":"We provide 100% placement assistance with interviews until you are placed."},{"question":"Can I attend a demo class?","answer":"Yes. Book a free demo for any course."},{"question":"Are online classes available?","answer":"Yes. Live online batches with recordings are available."},{"question":"Can I pay fees in instalments?","answer":"Yes. Easy EMI options are available on all major courses."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'skillsetu';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'skillsetu' and c.slug in ('training-institute', 'online-education', 'it-company');

