values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'kalakshetra-academy' and v.version = '1.0.0'), 'photo-points', 'Photo and points', '{"eyebrow":"Our story","title":"Keeping our arts alive","text":"Kalakshetra was founded by a family of musicians to share India''s rich musical and dance traditions. Students learn in the guru–shishya spirit, with modern methods and regular performances.","image":{"src":"/themes/kalakshetra-academy/place-1.svg","alt":"Keeping our arts alive"},"points":[{"title":"Experienced gurus","text":"Trained in respected gharanas.","icon":"music"},{"title":"Graded exams","text":"Gandharva and Prayag exam preparation.","icon":"sparkles"},{"title":"Performances","text":"Stage shows and recitals every year.","icon":"mic"},{"title":"All ages","text":"Classes for children and adults.","icon":"trophy"}],"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"points":{"maxItems":6,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["sprout","book","palette","music","puzzle","apple","sun","heart","shield","bus","trees","brush","smile","star","activity","armchair","baby","badge","percent","banknote","bed","briefcase","building","cake","camera","car","chart","chef-hat","code","coffee","compass","cpu","croissant","dumbbell","flower","gem","gift","globe","hammer","hand-heart","hard-hat","heart-pulse","house","key","laptop","leaf","lightbulb","map-pin","megaphone","mic","mountain","newspaper","party","pen","pill","plane","rocket","ruler","scale","scissors","shopping-bag","cart","shirt","smartphone","sparkles","stethoscope","tag","target","ticket","truck","tv","umbrella","utensils","wallet","wine","wrench","calculator","flame","graduation-cap","rupee","landmark","languages","radio","school","tractor","trophy","users","video"]}},"required":["title","icon"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","points","image"],"additionalProperties":false}'::jsonb, 120);
