values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'kalakshetra-academy' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"Our gurus","members":[{"name":"Pandit Suresh Kulkarni","role":"Hindustani Vocal","image":{"src":"/themes/kalakshetra-academy/person-1.svg","alt":"Pandit Suresh Kulkarni"}},{"name":"Smt. Anuradha Iyer","role":"Bharatanatyam","image":{"src":"/themes/kalakshetra-academy/person-2.svg","alt":"Smt. Anuradha Iyer"}},{"name":"Ustad Imran Qureshi","role":"Tabla","image":{"src":"/themes/kalakshetra-academy/person-3.svg","alt":"Ustad Imran Qureshi"}},{"name":"Ms. Riya Desai","role":"Kathak","image":{"src":"/themes/kalakshetra-academy/person-4.svg","alt":"Ms. Riya Desai"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'kalakshetra-academy' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"What is the right age to start?","answer":"Children can start music and dance from age five. Adults are welcome at any age."},{"question":"Do you prepare for exams?","answer":"Yes. We prepare students for Gandharva Mahavidyalaya and Prayag Sangeet Samiti exams."},{"question":"How often are classes?","answer":"Most courses have two classes a week."},{"question":"Do you teach online?","answer":"Yes. Many students learn with us online from India and abroad."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'kalakshetra-academy';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'kalakshetra-academy' and c.slug in ('training-institute', 'entertainment');

