select id, '1.0.0', 'shiksha-mahavidyalaya', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"campus-hero","props":{"eyebrow":"NAAC A grade · Affiliated to State University","title":"Quality higher education, close to home","text":"Undergraduate and postgraduate programmes in arts, science, commerce and computer applications, with excellent faculty and affordable fees.","primaryButton":{"label":"Apply online","href":"/contact"},"secondaryButton":{"label":"View courses","href":"/courses"},"image":{"src":"/themes/shiksha-mahavidyalaya/hero.svg","alt":"Shiksha Mahavidyalaya"},"facts":[{"value":"1971","label":"Established"},{"value":"4,500","label":"Students"},{"value":"28","label":"Programmes"},{"value":"NAAC A","label":"Accredited"}]}},{"type":"quick-links","props":{"items":[{"title":"Courses","text":"B.A.","icon":"graduation-cap","href":"/courses"},{"title":"About us","text":"Experienced faculty","icon":"book","href":"/about"},{"title":"Campus","text":"See our work","icon":"users","href":"/campus"},{"title":"Contact","text":"Mon – Sat · 10:00 AM – 4:00 PM","icon":"landmark","href":"/contact"}]}},{"type":"welcome","props":{"eyebrow":"Principal''s desk","title":"Empowering students for a brighter future","text":"Shiksha Mahavidyalaya has served students from the region for over fifty years. We offer quality education at affordable fees, with scholarships, a modern library and strong placement support.","quote":"Education is the most powerful tool for social change.","name":"Prof. (Dr.) Ramesh Chandra","role":"Principal","image":{"src":"/themes/shiksha-mahavidyalaya/place-1.svg","alt":"Prof. (Dr.) Ramesh Chandra"},"button":{"label":"About us","href":"/about"}}},{"type":"stats","props":{"items":[{"value":"1971","label":"Established"},{"value":"4,500","label":"Students"},{"value":"28","label":"Programmes"},{"value":"NAAC A","label":"Accredited"}]}},{"type":"programs","props":{"eyebrow":"Courses","title":"Undergraduate and post