values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'gyan-digital' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Is there a free trial?","answer":"Yes. Every course has a free 7-day trial."},{"question":"Can I learn in Hindi?","answer":"Yes. All courses are available in Hindi and English."},{"question":"Does it work on slow internet?","answer":"Yes. Our app is designed for low data use and offline downloads."},{"question":"How do I pay?","answer":"Pay by UPI, cards or net banking."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'gyan-digital';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'gyan-digital' and c.slug in ('online-education', 'coaching-institute', 'training-institute');

