values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'rangmanch-media' and v.version = '1.0.0'), 'play-hero', 'Playful hero', '{"title":"Entertainment that feels like","highlight":"home","text":"Original web series, film reviews, celebrity chats and regional stories, made for audiences across India.","primaryButton":{"label":"Watch now","href":"/contact"},"secondaryButton":{"label":"Our shows","href":"/shows"},"badges":[{"label":"45 lakh subscribers"},{"label":"300+ episodes"},{"label":"8 languages"},{"label":"12 awards"}],"image":{"src":"/themes/rangmanch-media/hero.svg","alt":"Rangmanch Media"},"smallImage":{"src":"/themes/rangmanch-media/scene-2.svg","alt":"Choti Si Baat"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"highlight":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"primaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"secondaryButton":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badges":{"maxItems":4,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200}},"required":["label"],"additionalProperties":false}},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"smallImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","badges","image"],