values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'rangmanch-media' and v.version = '1.0.0'), 'teachers', 'Teacher circles', '{"eyebrow":"Our team","title":"The team","members":[{"name":"Kabir Malhotra","role":"Founder & Creative Head","image":{"src":"/themes/rangmanch-media/person-1.svg","alt":"Kabir Malhotra"}},{"name":"Shreya Ghosh","role":"Head of Content","image":{"src":"/themes/rangmanch-media/person-2.svg","alt":"Shreya Ghosh"}},{"name":"Varun Bhatia","role":"Director","image":{"src":"/themes/rangmanch-media/person-3.svg","alt":"Varun Bhatia"}},{"name":"Ananya Pillai","role":"Host","image":{"src":"/themes/rangmanch-media/person-4.svg","alt":"Ananya Pillai"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"members":{"minItems":1,"maxItems":12,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"fact":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 140);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'rangmanch-media' and v.version = '1.0.0'), 'faq', 'Parent questions', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Where can I watch your shows?","answer":"On our website, app and all major video platforms."},{"question":"Can brands collaborate with you?","answer":"Yes. Contact our brand studio for campaigns and sponsorships."},{"question":"Do you accept scripts?","answer":"We review scripts from new writers every quarter."},{"question":"Are you hiring?","answer":"We regularly hire editors, writers and production staff."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 150);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'rangmanch-media';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'rangmanch-media' and c.slug in ('entertainment', 'news', 'magazine');

