values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'yatra-patrika' and v.version = '1.0.0'), 'page-header', 'Page header', '{"eyebrow":"About us","title":"Travel slowly, see deeply","text":"Yatra Patrika celebrates India beyond the usual tourist spots. Our writers live with local families, walk old trade routes and eat at roadside dhabas, so you can travel with respec","image":{"src":"/themes/yatra-patrika/place-2.svg","alt":"Yatra Patrika"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["title","image"],"additionalProperties":false}'::jsonb, 100);
