values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'yatra-patrika' and v.version = '1.0.0'), 'welcome', 'Principal''s welcome', '{"eyebrow":"From the editor","title":"Travel slowly, see deeply","text":"Yatra Patrika celebrates India beyond the usual tourist spots. Our writers live with local families, walk old trade routes and eat at roadside dhabas, so you can travel with respect and curiosity.","quote":"India rewards those who slow down and listen.","name":"Malini Iyer","role":"Editor","image":{"src":"/themes/yatra-patrika/place-1.svg","alt":"Malini Iyer"},"button":{"label":"About us","href":"/about"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"quote":{"type":"string","minLength":1,"maxLength":2000},"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","name","image"],"additionalProperties":false}'::jsonb, 120);
