values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'yatra-patrika' and v.version = '1.0.0'), 'programs', 'Program cards', '{"eyebrow":"Sections","title":"Inside every issue","text":"Published monthly in print and online.","items":[{"title":"Pahad","tag":"Mountains","text":"Treks, villages and homestays in the Himalayas.","image":{"src":"/themes/yatra-patrika/scene-1.svg","alt":"Pahad"},"href":"/sections"},{"title":"Sagar","tag":"Coasts","text":"Beaches, fishing villages and island life.","image":{"src":"/themes/yatra-patrika/scene-2.svg","alt":"Sagar"},"href":"/sections"},{"title":"Teerth","tag":"Pilgrimage","text":"Temples, ghats and spiritual journeys.","image":{"src":"/themes/yatra-patrika/scene-3.svg","alt":"Teerth"},"href":"/sections"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":9,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"tag":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"href":{"type":"string","maxLength":2048}},"required":["title","image"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
