insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'hisaab-associates' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"What documents are needed for ITR?","answer":"PAN, Aadhaar, Form 16, bank statements and investment proofs. We send a checklist."},{"question":"Do you handle GST notices?","answer":"Yes. We reply to GST and income tax notices and represent clients."},{"question":"Can you help a new startup?","answer":"Yes. We handle registration, GST, accounting and compliance for startups."},{"question":"Do you work online?","answer":"Yes. Most clients share documents online and never need to visit."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'hisaab-associates';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'hisaab-associates' and c.slug in ('chartered-accountant', 'financial-services', 'consulting');

