values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'arogya-ayurveda' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Are Ayurvedic medicines safe?","answer":"Our medicines are made from quality-tested herbs and prescribed by qualified doctors."},{"question":"How long is a Panchakarma programme?","answer":"Usually 7 to 21 days, depending on your condition."},{"question":"Can I continue my allopathic medicines?","answer":"Yes. Your vaidya will guide you. Never stop medicines without your doctor''s advice."},{"question":"Do you offer online consultation?","answer":"Yes. Video consultations are available with medicines delivered home."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'arogya-ayurveda';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'arogya-ayurveda' and c.slug in ('medical-clinic', 'spa', 'yoga');

