insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'kuber-finserv' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Do you charge for advice?","answer":"Eligibility checks and advice are free. Any fees are explained before you apply."},{"question":"Which banks do you work with?","answer":"We work with 40+ banks, NBFCs and insurance companies."},{"question":"What documents are needed for a home loan?","answer":"KYC, income proof, bank statements and property papers. We send a checklist."},{"question":"Are mutual funds safe?","answer":"Mutual funds carry market risk. We recommend funds based on your goals and risk profile."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'kuber-finserv';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'kuber-finserv' and c.slug in ('financial-services', 'insurance', 'chartered-accountant');

