select id, '1.0.0', 'ghar-ka-khana', '1.0.0', 'stable', '{"pages":[{"title":"Home","slug":"home","isHome":true,"sections":[{"type":"play-hero","props":{"title":"Healthy, homemade food,","highlight":"delivered daily","text":"Fresh dal, sabzi, roti and rice cooked with less oil, delivered hot to your office, hostel or home.","primaryButton":{"label":"Start my tiffin","href":"/contact"},"secondaryButton":{"label":"See meal plans","href":"/meal-plans"},"badges":[{"label":"2,500+ daily tiffins"},{"label":"₹99 meals from"},{"label":"Fresh cooked daily"},{"label":"4.8★ rating"}],"image":{"src":"/themes/ghar-ka-khana/hero.svg","alt":"Ghar Ka Khana Tiffin"},"smallImage":{"src":"/themes/ghar-ka-khana/scene-2.svg","alt":"Mini meal"}}},{"type":"stats","props":{"items":[{"value":"2,500+","label":"Daily tiffins"},{"value":"₹99","label":"Meals from"},{"value":"Fresh","label":"Cooked daily"},{"value":"4.8★","label":"Rating"}]}},{"type":"classes","props":{"eyebrow":"Meal plans","title":"Choose your plan","text":"Daily, weekly and monthly subscriptions.","items":[{"title":"Regular thali","ages":"Veg","text":"Dal, sabzi, 4 roti, rice and salad.","image":{"src":"/themes/ghar-ka-khana/scene-1.svg","alt":"Regular thali"},"color":"sun"},{"title":"Mini meal","ages":"Light","text":"Sabzi, 3 roti and dal for a lighter lunch.","image":{"src":"/themes/ghar-ka-khana/scene-2.svg","alt":"Mini meal"},"color":"coral"},{"title":"Jain meal","ages":"No onion-garlic","text":"Pure Jain food cooked separately.","image":{"src":"/themes/ghar-ka-khana/scene-3.svg","alt":"Jain meal"},"color":"mint"}]}},{"type":"photo-points","props":{"eyebrow":"Our story","title":"Started for students far from home","text":"Ghar Ka Khana began in a home kitchen, cooking for students and working people who missed home food. We still cook every meal fresh, with seasonal vegetables and simple, healthy recipes.","image":{"src":"/themes/ghar-ka-khana/place-1.svg","alt":"Started for students far from home"},"points":[{"title":"Cooked fresh","text":"Every meal cooked the same morning.","icon":"utensils"},{"title":"Less oil","text":"Healthy recipes with less oil and spice.","icon":"truck"},{"title":"Hygienic","text":"FSSAI licensed kitchen.","icon":"leaf"},{"title":"Changing menu","text":"A different menu every day.","icon":"heart"}],"button":{"label":"About us","href":"/about"}}},{"type":"day-timeline","props":{"eyebrow":"How it works","title":"How it works","text":"Start your tiffin in minutes.","items":[{"time":"Step 1","title":"Choose","text":"Select your meal plan.","icon":"utensils"},{"time":"Step 2","title":"Subscribe","text":"Pay weekly or monthly by UPI.","icon":"truck"},{"time":"Step 3","title":"Receive","text":"Hot food delivered to your door.","icon":"leaf"},{"time":"Step 4","title":"Enjoy","text":"Pause, skip or change anytime.","icon":"heart"}]}},{"type":"teachers","props":{"eyebrow":"Our team","title":"Our kitchen family","members":[{"name":"Sunita Kulkarni","role":"Founder","image":{"src":"/themes/ghar-ka-khana/person-1.svg","alt":"Sunita Kulkarni"}},{"name":"Lata Bai","role":"Head Cook","image":{"src":"/themes/ghar-ka-khana/person-2.svg","alt":"Lata Bai"}},{"name":"Rajesh Patil","role":"Delivery Head","image":{"src":"/themes/ghar-ka-khana/person-3.svg","alt":"Rajesh Patil"}},{"name":"Pooja Shinde","role":"Customer Care","image":{"src":"/themes/ghar-ka-khana/person-4.svg","alt":"Pooja Shinde"}}]}},{"type":"testimonials","props":{"heading":"What our clients say","items":[{"quote":"Finally, food that tastes like my mother''s cooking.","author":"Aditya Sharma","role":"Student"},{"quote":"Healthy, tasty and always on time.","author":"Neha Joshi","role":"IT professional"},{"quote":"The Jain meals are perfect for my parents.","author":"Mitesh Shah","role":"Customer"}]}},{"type":"cta","props":{"heading":"Started for students far from home","body":"First tiffin free for new subscribers","button":{"label":"Start my tiffin","href":"/contact"}}}]},{"title":"About","slug":"about","sections