values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'swarna-jewellers' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"Is all your gold hallmarked?","answer":"Yes. Every gold piece is BIS hallmarked with a unique HUID number."},{"question":"Do you have a gold saving scheme?","answer":"Yes. Pay monthly for 11 months and we add the 12th instalment."},{"question":"Can I exchange old gold?","answer":"Yes. We exchange old gold at the current rate after testing purity."},{"question":"Do you make custom designs?","answer":"Yes. Our karigars can make jewellery to your own design."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'swarna-jewellers';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'swarna-jewellers' and c.slug in ('jewellery', 'fashion', 'wedding-planner');

