insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'shri-mandir-trust' and v.version = '1.0.0'), 'faq', 'Questions and answers', '{"eyebrow":"Questions","title":"Frequently asked questions","items":[{"question":"What are the darshan timings?","answer":"The temple is open from 5:00 AM to 12:30 PM and 4:00 PM to 9:30 PM every day."},{"question":"Can I book a pooja online?","answer":"Yes. Poojas can be booked online, and prasad can be sent to your address."},{"question":"Are donations tax exempt?","answer":"Yes. Donations to the trust are eligible for tax benefits under Section 80G."},{"question":"Is there accommodation for devotees?","answer":"A dharamshala with simple rooms is available on request."}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"items":{"minItems":1,"maxItems":16,"type":"array","items":{"type":"object","properties":{"question":{"type":"string","minLength":1,"maxLength":200},"answer":{"type":"string","minLength":1,"maxLength":2000}},"required":["question","answer"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'shri-mandir-trust';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'shri-mandir-trust' and c.slug in ('temple', 'ngo');

